// jQuery init
$jq = jQuery.noConflict();
window.menu_offsettop = 60;
window.stickyheader_active = false;

var app = {};

/*window.addEventListener("orientationchange", function() {
 document.location.href = document.location.href;
 }, false);*/
jQuery(document).ready(function ($jq) {
    // run test on initial page load
    loadMenuPromo();
    moveNavigation();
    toggleSearchDiv();
    mobilenavigationinit();
    pageinit();
    initprintbutton();
    UserGeoLocationTrigger();
    telLinkSupportCheck();
    captchaDefaultValue();
    initWidgetLocSearchAutocomplete();
    initWidgetstate();
    app.backToTopButton = new BackToTopButton($jq('#back-to-top-button'),  {
        hideBefore: 500,
        hideAfter: 100
    });
});
jQuery(window).resize(function ($jq) {
    // run test on initial page load
    moveNavigation();
    toggleSearchDiv();
    pageinit();
    initprintbutton();
    mobilenavigationinit();
    UserGeoLocationTrigger();
    captchaDefaultValue();
    checkPromoImgs();
});

function toggleSearchDiv() {
    if (is_mobile()) {
        if (!$jq('#mobilesearch').find('.searchinputform').length) {
            $jq('.searchinputform').attr('id', 'mobilesearch_input');
            $jq('.searchinputform').addClass('mobilesearch');
            $jq('.searchinputform').detach().last().appendTo('#mobilesearch');
            $jq('#inner-meta-nav ul li').addClass('metanavli');
            $jq('#inner-meta-nav ul li a').addClass('toplink');
            $jq('.metanavli').detach().appendTo('#navigation_ul .metanav-mobile');
            $jq('#mainnav').addClass('mobilehide');
            $jq('#menu_subnav*').css('left', 0);
            $jq('#searchnav').addClass('mobilehide');
        }
    } else {
        $jq('#mainnav').removeClass('mobileshow');
        $jq('#mainnav').removeClass('mobilehide');
        $jq('#searchnav').removeClass('mobileshow').addClass('mobilehide');
        $jq('body').removeClass('noscroll');
        if (!$jq('#searchinput_div').find('mobilesearch_input').length) {
            //alert( 'put search back');
            $jq('.searchinputform').removeClass('mobilesearch');
            $jq('.searchinputform').detach().appendTo('#searchinput_div');
            $jq('#mobilesearch').empty();
            // $jq('#mobilesearch').detach().appendTo('#navigation_ul');
        }
        if ($jq('.metanavli').length) {
            $jq('.metanavli').detach().appendTo('#inner-meta-nav ul');
            $jq('#inner-meta-nav ul li').removeClass('metanavli');
            $jq('#inner-meta-nav ul li a').removeClass('toplink');
            $jq('#tracking').detach().appendTo('#headerfunctions .row');
        }
    }
}

function mobilenavigationinit() {
    /* Top-Navigation Click & Touch Handling */
    var topnavlink = '';
    var secondlevellink = '';
    $jq('#navicon').unbind('touchstart click');
    $jq('#searchicon').unbind('touchstart click');
    $jq('.secondlevellink').unbind('touchstart click');
    $jq('.navcontrol').unbind('touchstart click');
    $jq('.toplink').unbind('touchstart click');
    $jq('.secondlevellink').unbind('touchstart click');
    $jq('.navcontrol_down').unbind('touchstart click');
    $jq('.navcontrol_top_mobile_down').unbind('touchstart click');
    $jq('.navcontrol_top_mobile').unbind('touchstart click');
    $jq('.headerfunctions--mobile a.collapse').unbind('click');
    $jq("#navicon").on('click', function (event) {
        event.preventDefault();
        $jq('#mobile-navicons .active').removeClass('active'); // alle mobilen navicons deaktivieren
        if ($jq('#mainnav').hasClass('mobilehide')) {
            changeClass($jq('#mainnav'), 'mobilehide', 'mobileshow');
            $jq('body').addClass('noscroll'); // wenn mainmenu aktiv, scrollen von body deaktivieren
            $jq(this).parent().addClass('active'); // navicon aktivieren
            $jq('#tracking').detach().appendTo('#mainnav .headerfunctions--tracking .subnav').show();
        } else {
            changeClass($jq('#mainnav'), 'mobileshow', 'mobilehide');
            $jq('body').removeClass('noscroll');
            $jq('#tracking').detach().appendTo('#headerfunctions .row');
        }
        if ( $jq('#searchnav').hasClass('mobileshow') ) {
            $jq('#searchnav').removeClass('mobileshow').addClass('mobilehide');
        }
    });
    $jq("#searchicon").on('click', function (event) {
        event.preventDefault();
        $jq('#mobile-navicons .active').removeClass('active'); // alle mobilen navicons deaktivieren
        if ( !$jq('#searchnav').hasClass('mobileshow') ) {
            // search navi anzeigen
            $jq(this).parent().addClass('active'); // navicon aktivieren
            $jq('#searchnav').addClass('mobileshow').removeClass('mobilehide');
            $jq('#tracking').detach().appendTo('#searchnav .headerfunctions--tracking .subnav').show();
        } else {
            $jq('#searchnav').removeClass('mobileshow').addClass('mobilehide');
            $jq('#tracking').detach().appendTo('#headerfunctions .row');
        }
        if ($jq('#mainnav').hasClass('mobileshow')) {
            changeClass($jq('#mainnav'), 'mobileshow', 'mobilehide');
            $jq('body').removeClass('noscroll');
        }
    });
    if (!is_touch_device()) {
        $jq('.subnavclose').hide();
    }
    if ($jq('.subnav').width() > 1139) {
        $jq('.navcontrol').attr('style', '');
        $jq('.navcontrol_down').attr('style', '');
    }
    $jq('.subnavclose').on('click', function (event) {
        event.preventDefault();
        $jq('#navoverlay').removeClass('navoverlay');
        $jq('.subnavclose').attr('style', 'opacity:0; visibility:hidden; z-index: 1030;');
        $jq('.subnav').attr('style', 'opacity:0; visibility:hidden; z-index: 1030;');
        topnavlink = '';
        secondlevellink = '';
        // window.stickyheader_active = true;
        return false;
    });
    $jq('.toplink').bind('click', function (event) {
        event.preventDefault();
        var $navcontrol = $jq(this).next('.navcontrol_top_mobile, .navcontrol_top_mobile_down');
        if ( $jq('.subnav').width() > 1139) {
            document.location.href = $jq(this).attr('href');
            return true;
        } else if ( is_mobile() && $navcontrol.length > 0 ) {
            $navcontrol.trigger('touchstart');
            return false;
        } else {
            window.stickyheader_active = false;
            // reset formerly closed subnavs
            $jq('.subnav').removeAttr('style');
            if (!$jq(this).parent().find('.subnav').length) {
                document.location.href = $jq(this).attr('href');
            }
            if ($jq(this).attr('href') == topnavlink) {
                document.location.href = topnavlink;
            } else {
                topnavlink = $jq(this).attr('href');
                if (is_mobile()) {
                    $jq('.navcontrol_top_mobile_down').addClass('navcontrol_top_mobile');
                    $jq('.navcontrol_top_mobile_down').removeClass('navcontrol_top_mobile_down');
                    changeClass($jq(this).parent().find('.navcontrol_top_mobile'), 'navcontrol_top_mobile', 'navcontrol_top_mobile_down');
                    $jq(this).parent().find('.subnav').attr('style', 'opacity: 1; visibility:visible; z-index: 2002; display:block;');
                } else {
                    // close others
                    $jq('.subnav').removeAttr('style');
                    // open my subnav
                    $jq(this).parent().find('.subnavclose').attr('style', 'opacity: 1; visibility:visible; z-index: 2001;');
                    $jq(this).parent().find('.subnav').attr('style', 'opacity: 1; visibility:visible; z-index: 2002;');
                }
            }
            return false;
        }
    });
    if (!is_touch_device()) {
        $jq('.navcontrol_top_mobile').on('click', function (event) {
            $jq(this).trigger('touchstart');
        });
    }
    $jq('.navcontrol_top_mobile, .navcontrol_top_mobile_down').bind('touchstart', function (event) {
        event.preventDefault();
        if (is_mobile()) {
            // reset formerly closed subnavs
            $jq('.subnav').removeAttr('style');
            if ($jq(this).hasClass('navcontrol_top_mobile')) {
                $jq('.navcontrol_top_mobile_down').addClass('navcontrol_top_mobile');
                $jq('.navcontrol_top_mobile_down').removeClass('navcontrol_top_mobile_down');
                changeClass($jq(this), 'navcontrol_top_mobile', 'navcontrol_top_mobile_down');
                $jq(this).parent().find('.subnav').attr('style', 'opacity: 1; visibility:visible; z-index: 2002; display:block;');
            } else {
                changeClass($jq(this), 'navcontrol_top_mobile_down', 'navcontrol_top_mobile');
                $jq(this).parent().find('.subnav').removeAttr('style');
                topnavlink = '';
            }
            return false;
        }
    });
    $jq('.headerfunctions--mobile a.collapse').bind('click', function(event) {
        event.preventDefault();
        var $navcontrol = $jq(this).parent().find('.navcontrol_top_mobile');
        var $navcontrol_down = $jq(this).parent().find('.navcontrol_top_mobile_down');
        if ( $navcontrol.length > 0 ) $navcontrol.trigger('touchstart');
        else if ( $navcontrol_down.length > 0 ) $navcontrol_down.trigger('touchstart');
    });
    if (!is_touch_device()) {
        $jq('.navcontrol').on('click', function (event) {
            $jq(this).trigger('touchstart');
        });
    }
    $jq('.navcontrol, .navcontrol_down').on('touchstart', function (event) {
        event.preventDefault();
        if ($jq('.subnav').width() < 1140) {
            if ($jq(this).hasClass('navcontrol')) {
                $jq('.navcontrol_down').addClass('navcontrol');
                $jq('.navcontrol_down').removeClass('navcontrol_down');
                changeClass($jq(this), 'navcontrol', 'navcontrol_down');
            } else {
                changeClass($jq(this), 'navcontrol_down', 'navcontrol');
                secondlevellink = '';
            }
            toggleSecondlevelSubnav($jq(this).parent().find('ul'), '');
            return false;
        }
    });
    $jq('.secondlevellink').on('click', function (event) {
        event.preventDefault();
        var $navcontrol = $jq(this).next('.navcontrol, .navcontrol_down');

        if ( $jq('.subnav').width() > 1139) {
            document.location.href = $jq(this).attr('href');
            return true;
        } else if ( is_mobile() && $navcontrol.length > 0 ) {
            $navcontrol.trigger('touchstart');
            return false;
        }
        if ($jq('.subnav').width() < 1140) {
            if ($jq(this).attr('href') == secondlevellink) {
                document.location.href = secondlevellink;
            } else {
                if ($jq(this).parent().find('.navcontrol').hasClass('navcontrol')) {
                    $jq('.navcontrol_down').addClass('navcontrol');
                    $jq('.navcontrol_down').removeClass('navcontrol_down');
                    changeClass($jq(this).parent().find('.navcontrol'), 'navcontrol', 'navcontrol_down');
                } else {
                    changeClass($jq(this).parent().find('.navcontrol_down'), 'navcontrol_down', 'navcontrol');
                }
                secondlevellink = $jq(this).attr('href');
                toggleSecondlevelSubnav($jq(this).parent().find('ul'), secondlevellink);
                return false;
            }
        }
    });
    $jq('.thirdlevellink').bind('click', function (event) {
        window.stickyheader_active = false;
        document.location.href = $jq(this).attr('href');
        return true;
    });
    $jq('.searchinputform').find('input').bind('click', function (event) {
        // no resize if softkeyboard is launched
        $jq(window).unbind('resize');
        $jq(this).focus();
    });
}

function toggleFirstlevelSubnav(ulelem, href) {
    if (ulelem.length) {
        if (ulelem.css('display') == 'none') {
            ulelem.show();
        } else {
            ulelem.hide();
        }
    } else {
        if (href.length) {
            document.location.href = href;
        }
    }
}

function toggleSecondlevelSubnav(ulelem, href) {
    if (ulelem.length) {
        if (ulelem.css('display') == 'none') {
            $jq('.thirdlevel').hide();
            ulelem.show();
        } else {
            ulelem.hide();
        }
    } else {
        if (href.length) {
            document.location.href = href;
        }
    }
}

function pageinit() {
    if (navigator.userAgent.toLowerCase().indexOf("chrome") >= 0) {
        $jq('.headerfunctions input').attr('autocomplete', 'off');
    }
    $jq('figure.responsive').picture();
    $jq('#btn-prices').unbind('touchstart click');
    $jq('#btn-places').unbind('touchstart click');
    $jq('#btn-tracking').unbind('touchstart click');
    $jq('.widgetclose').unbind('touchstart click');
    $jq('h3').unbind('click touchstart mouseenter mouseleave');
    $jq('li').unbind('mouseenter mouseleave');
    $jq('li').off('hover');
    $jq('a').unbind('mouseenter mouseleave');
    $jq('a').off('hover');
    $jq('.subnav').hover(function () {
        $jq('#navoverlay').addClass('navoverlay');
    });
    $jq('.subnav').mouseleave(function () {
        $jq('#navoverlay').removeClass('navoverlay');
    });
    $jq('.toplink').hover(function () {
        //alert($jq(this).parent().find('.subnav').attr('class'));
        if ($jq(this).parent().find('.subnav').attr('class') == 'subnav') {
            $jq('#navoverlay').addClass('navoverlay');
        }
    });
    $jq('.toplink').mouseleave(function () {
        $jq('#navoverlay').removeClass('navoverlay');
    });
    var menu_initialoffset = $jq('header').offset().top;
    $jq(window).scroll(function () {
        if (window.stickyheader_active) {
            var header = $jq('header');
            if ($jq(this).scrollTop() > (menu_initialoffset + window.menu_offsettop) && $jq('header').css('position') != 'fixed') {
                $jq('header').css({
                    'position': 'fixed'
                });
                $jq('header').css({
                    'margin-left': $jq('#pagewrap').css('margin-left')
                });
                $jq('header').css({
                    'top': -menu_initialoffset - window.menu_offsettop
                });
                $jq('header').addClass('stickyheader');
            }
            if (($jq(this).scrollTop() < (menu_initialoffset + window.menu_offsettop) && $jq('header').css('position') == 'fixed') || $jq('#mainnav').hasClass('mobileshow')) {
                $jq('header').css({
                    position: '',
                    'top': '',
                    'margin-left': ''
                });
                $jq('header').removeClass('stickyheader');
            }
        }
    });
    $jq('.navigation li.firstlevel').mouseover(function () {

        var main_node = $jq(this).attr('id');
        var main_id = main_node.replace("mainnode", "");
        var isie = msieversion();

        if (window.matchMedia("only screen and (min-width: 1157px)").matches == true) {

            var leftPromo = $jq('#menu_left_promo' + main_id).hasClass('promoimgwrapper');
            var rightPromo = $jq('#menu_right_promo' + main_id).hasClass('promoimgwrapper');

            if (leftPromo == true || rightPromo == true) {

                var puffer = 30;
                var versatz = $jq(this).data('versatz');
                var position_first_left = $jq(this).find('a.secondlevellink:first').position().left;


                var ul_width = $jq(this).data('ul_width');
                ul_width = ul_width + puffer;
                var menu_width = $jq(this).data('menu_width');

                var max_promo_width = (menu_width - ul_width) / 2;

                var menu_subnav_width = $jq('#innersubnav' + main_id).width() - max_promo_width - max_promo_width;

                if (isie) {
                    var substra = 32.44;
                    var max_vorschub = 22;
                } else {
                    var substra = 33.44;
                    var max_vorschub = 20;
                }

                var diff = versatz - position_first_left - max_promo_width;
                var vorschub = diff - substra;
                if (vorschub > max_vorschub) {
                    vorschub = max_vorschub;
                }

                $jq('#menu_subnav' + main_id).css('width', menu_subnav_width);
                $jq('#menu_subnav' + main_id + ' ul:first').css('position', 'relative');
                $jq('#menu_subnav' + main_id + ' ul:first').css('left', vorschub);
                $jq('#menu_subnav' + main_id).css('padding-left', 0);
                $jq('#menu_subnav' + main_id).css('padding-right', puffer);
                if (isie) {
                    $jq('#menu_subnav' + main_id + ' li.n-secondlevel-li').css('margin-left', 15);
                }

                if (leftPromo) {
                    $jq('#menu_left_promo' + main_id).css('display', 'table-cell');
                    $jq('#menu_left_promo' + main_id).css('width', max_promo_width);
                }
                if (rightPromo) {
                    $jq('#menu_right_promo' + main_id).css('display', 'table-cell');
                    $jq('#menu_right_promo' + main_id).css('width', max_promo_width);
                }
            } else {
                versatz = Math.abs($jq(this).position().left) - 15;

                $jq('#menu_left_promo' + main_id).css('display', 'none');
                $jq('#menu_subnav' + main_id).css('width', '100%');
                $jq('#menu_subnav' + main_id).css('padding-left', versatz);
                $jq('#menu_right_promo' + main_id).css('display', 'none');
            }

        } else if (window.matchMedia("only screen and (min-width: 1149px)").matches) {
            if (main_id == 6) {
                var diff = 5;
            } else {
                var diff = 15;
            }
            versatz = Math.abs($jq(this).position().left) - diff;

            $jq('#menu_left_promo' + main_id).css('display', 'none');
            $jq('#menu_subnav' + main_id).css('width', '100%');
            $jq('#menu_subnav' + main_id).css('padding-left', versatz);
            $jq('#menu_right_promo' + main_id).css('display', 'none');
        }
    });
    $jq('.footerlinklist h3').bind('click', function (event) {
        event.preventDefault();
        $jq(this).trigger('touchstart');
        return false;
    });
    $jq('.footerlinklist h3').bind('touchstart', function (event) {
        event.preventDefault();
        $jq(this).parent().parent().find('ul').toggleClass('active');
        // close all other popups
        $jq('.footerlinklist').find('ul').not($jq(this).parent().parent().find('ul')).removeClass('active');
        return false;
    });
    $jq('.footerlinklist ul li').on('click', function (e) {
        window.location.href = $jq(this).find('a').attr('href');
    });
    $jq('.linkdropdown h2').bind('click', function (event) {
        event.preventDefault();
        $jq(this).trigger('touchstart');
        return false;
    });
    $jq('.linkdropdown h2').bind('touchstart', function (event) {
        event.preventDefault();
        $jq(this).parent().parent().find('ul').toggleClass('active');
        $jq(this).parent().parent().find('a').toggleClass('cta');
        // close all other popups
        $jq('.linkdropdown').find('ul').not($jq(this).parent().parent().find('ul')).removeClass('active');
        return false;
    });
    $jq('.linkdropdown ul li').on('click', function (e) {
        window.location.href = $jq(this).find('a').attr('href');
    });
    /* cta header */
    $jq('#btn-places').click(function () {
        $jq('#tracking').hide();
        $jq('#prices').hide();
        $jq('#places').toggle();
    });
    $jq('#places').find('.widgetclose').click(function () {
        $jq('#places').toggle();
    });
    $jq('#btn-prices').click(function () {
        $jq('#places').hide();
        $jq('#tracking').hide();
        //$jq('#prices').toggle();
    });
    $jq('#prices').find('.widgetclose').click(function () {
        $jq('#prices').toggle();
    });
    $jq('#btn-tracking').click(function () {
        $jq('#places').hide();
        $jq('#prices').hide();
        $jq('#tracking').toggle();
    });
    $jq('#tracking').find('.widgetclose').click(function () {
        $jq('#tracking').toggle();
    });
    /* initialize portocalculator */
    try {
        init_portocalculator();
    } catch (e) {
    }
    $jq('#gallery-id-30').slideshow({
        autoScroll: true,
        speed: 6000
    });
    $jq('#gallery-id-40').slideshow({
        autoScroll: true,
        speed: 7000,
        transition: 450,
    });
    $jq('.gallery-pagination').slideshowPager();
    $jq('#edit-submitted-salutation, #edit-submitted-subject ').change(function (event) {
        var caller = '#' + event.target.id;
        var current = $jq(caller).val();
        if (current != 'null' && current != '') {
            $jq(caller).css('color', 'black');
        } else {
            $jq(caller).css('color', 'gray');
        }
    });
    /* Some Androids does "support" maxlength, so do it via JS */
    max_length = $jq("#edit-tracking-number").attr("maxlength");
    $jq("#edit-tracking-number").on("keyup", function () {
        if (this.value.length >= max_length) {
            $jq(this).val($jq(this).val().substr(0, max_length));
        }
        return;
    });
}

function initWidgetstate() {
    if (window.location.search.indexOf('w=') > -1) {
        var items = location.search.substr(1).split("&");
        for (var index = 0; index < items.length; index++) {
            tmp = items[index].split("=");
            if (tmp[0] === 'w') {
                param = decodeURIComponent(tmp[1]).replace(/\+/g, " ");
                param = param.replace(/(<([^>]+)>)/ig, "");  // Strip Tags
                if (param == 1) {
                    $jq('#btn-places').click();
                }
                if (param == 2) {
                    $jq('#btn-prices').click();
                }

                if (param == 3) {
                    $jq('#btn-tracking').click();
                }
            }
        }
    }
}

function initprintpage(body) {
    $jq('#main').html(body);
    var document_focus = false; // var we use to monitor document focused status.
    $jq(document).ready(function () {
        window.print();
        document_focus = true;
    });
    setInterval(function () {
        if (document_focus === true) {
            window.close();
        }
    }, 300);
}

function initprintbutton() {
    // trackingprintfunction
    $jq(".tracking_printdiv").click(function () {
        var document_focus = false; // var we use to monitor document focused status.
        var body = '';
        body = body + '<section class="print">';
        body = body + '<article>';
        body = body + '<h1>PIN Sendungsverfolgung</h1>';
        body = body + '<h2>Sendung: ' + $jq('.tracking_number').text() + '</h2>';
        body = body + '<table>';
        body = body + '<tr><td>Sendungsnummer: </td><td>' + $jq('.tracking_number').text() + '</td></tr>';
        body = body + '<tr><td>Datum: </td><td>' + $jq('.tracking_date').text() + '</td></tr>';
        body = body + '<tr><td>Status: </td><td>' + $jq('.tracking_status').text() + '</td></tr>';
        body = body + '</table>';
        body = body + '</article>';
        body = body + '</section>';
        var content = $jq('#main').clone();
        $jq('#main').html(body);
        window.print();
        $jq('#main').empty();
        $jq('#main').replaceWith(content);
        if (isIE() == 8) {
            /* ie8 page rebuild */
            document.location.href = document.location.href;
        } else {
            /* restart Slideshow */
            $jq('.gallery-slider').slideshow({
                autoScroll: true,
                speed: 5000
            });
        }
    });
}

function isIE() {
    var myNav = navigator.userAgent.toLowerCase();
    return (myNav.indexOf('msie') != -1) ? parseInt(myNav.split('msie')[1]) : false;
}

function changeClass(elem, class1, class2) {
    if ($jq(elem).hasClass(class1)) {
        $jq(elem).removeClass(class1);
        $jq(elem).addClass(class2);
    } else {
        if ($jq(elem).hasClass(class2)) {
            $jq(elem).removeClass(class2);
            $jq(elem).addClass(class1);
        }
    }
}

function moveNavigation() {
    if ($jq("#navicon").css("visibility") == "hidden") {
        /* tablet */
        if ($jq("#logobackground").css("height") == '30px') {
            /* tablet landscape */
            window.menu_offsettop = 0;
        } else {
            if ($jq("#logobackground").css("height") == '40px') {
                /* desktop small */
                window.menu_offsettop = 10;
            } else {
                /* desktop */
                window.menu_offsettop = 15;
            }
        }
    } else {
        /* mobile */
        window.menu_offsettop = 0;
    }
}

function is_mobile() {
    return !($jq("#mobile-navicons").css("visibility") == "hidden");
}

function is_touch_device() {
    try {
        document.createEvent("TouchEvent");
        return true;
    } catch (e) {
        return false;
    }
}

function UserGeoLocationTrigger() {
    $jq('#users_geoloc').click(function (event) {
        logger('checked UserLocation');
        if (navigator.geolocation) { // Try HTML5 geolocation.
            navigator.geolocation.getCurrentPosition(function (position, error) {
                var pos = {
                    lat: position.coords.latitude,
                    lng: position.coords.longitude
                };
                logger("UserStandort ermittelt: " + pos.lat + "/" + pos.lng);
                var geocoder = new google.maps.Geocoder;
                geocoder.geocode({
                    'location': pos
                }, function (results, status) {
                    if (status === google.maps.GeocoderStatus.OK) {
                        if (results[1]) {
                            $jq('#locationSearchVal').val(results[1].formatted_address);
                            $jq('#widgetUserLat').val(position.coords.latitude);
                            $jq('#widgetUserLng').val(position.coords.longitude);
                            logger('Add ' + results[1] + ' as result');
                            $jq('form[name=locationsearch]').submit();
                        } else {
                            logger('No results found with given position');
                        }
                    } else {
                        logger('Geocoder seems to work, but returns no value. failed due to: ' + status);
                        $jq('#locationSearchVal').val('Berlin');
                        $jq('form[name=locationsearch]').submit();
                    }
                });
            }, function (error) {
                logger('General Error with GeoCoding:' + error);
                $jq('#locationSearchVal').val('Berlin')
                $jq('form[name=locationsearch]').submit();
            });
        } else {
            // Browser doesn't support Geolocation anyway
            logger('Errror with getting Position');
        }
    });
}

function outdatedIEBrowser() {
    var ua = window.navigator.userAgent;
    var msie = ua.indexOf("MSIE ");
    if (msie > 0) { // If Internet Explorer, return version number
        version = (parseInt(ua.substring(msie + 5, ua.indexOf(".", msie))));
        if (version <= 8) {
            var fromContent = document.getElementById("main").innerHTML;
            var layerContent = '<div class="messages error"><h2 style="color: red;">Ihr Browser ist veraltet.</h1>';
            layerContent += '<p>Sie nutzen den Internet Explorer ' + version + ' oder älter.</p>';
            layerContent += '<p>Für eine optimale Nutzung und zur Verhinderung von Sicherheitsproblemen sollten Sie Ihren Browser aktualieren.<br><br>&nbsp;</p>';
            layerContent += '<p><a href="http://windows.microsoft.com/de-DE/internet-explorer/download-ie">Hier</a> können Sie die aktuelle Version herunterladen.';
            layerContent += '</div>';
            document.getElementById('main').innerHTML = layerContent + fromContent;
        }
    } else { // If another browser, return 0
        //do nutting
    }
    return false;
}

function jumpToFormError() {
    var top = ($jq('.formWrapper').offset() || {
        "top": NaN
    }).top;
    $jq('html,body').animate({
        scrollTop: (top - 500)
    });
}

function printImg(img_id) {
    var src = jQuery(img_id).attr('src');
    var printWindow = window.open('', '', 'height=400,width=800');
    printWindow.document.write('<html><head><title>Sendungsbild</title>');
    printWindow.document.write('</head><body onload="print();" >');
    printWindow.document.write('<img width="100%" src="' + src + '" />');
    printWindow.document.write('</body></html>');
    printWindow.document.close();
}

function captchaDefaultValue() {
    if ($jq("#edit-captcha-response").length) {
        $jq("#edit-captcha-response").attr('placeholder', 'Sicherheitscode eingeben');
    }
}

function logger(s) {
    try {
        console.log(s)
    } catch (e) {
        // may use alert for IE, which does support console.log() e.g. IE8 //
    }
}

function telLinkSupportCheck() {
    if (is_touch_device()) {
        $jq('.phonenumber').attr('title', 'Klicken, um Anruf einzuleiten');
        $jq('.phonenumber').attr('alt', 'Klicken, um Anruf einzuleiten');
        $jq('.phonenumber').attr('href', 'tel: +4930577978800');
    } if (!is_touch_device()) {
        $jq('.phonenumber').attr('#'); // potentially not a phone
    }
}

function initWidgetLocSearchAutocomplete() {
    ac_widget_enabled = (Drupal.settings['pinstation_finder_module']['enabledGmapWidgetAutocomplete']);

    if (ac_widget_enabled == 'true') {
        autocomplete = new google.maps.places.Autocomplete(
            /** @type {!HTMLInputElement} */(document.getElementById('locationSearchVal')),
            {
                //bounds: acBounds,   // Restrict Autocompletion on defined bounds of Map
                types: ['geocode'],
                componentRestrictions: {
                    country: 'DE',
                },
            });
        autocomplete.addListener('place_changed', function () {
            $jq('form[name="locationsearch"]').submit();
        });
    }
}

function geolocate() {
    if (navigator.geolocation) {
        navigator.geolocation.getCurrentPosition(function (position) {
            var geolocation = {
                lat: position.coords.latitude,
                lng: position.coords.longitude
            };
            var circle = new google.maps.Circle({
                center: geolocation,
                radius: position.coords.accuracy
            });
            autocomplete.setBounds(circle.getBounds());
        });
    }
}

function loadMenuPromo() {
    var host = window.location.protocol + '//' + window.location.host + '/';
    $jq('#navigation_ul li.firstlevel').each(function () {
        var cur_node = $jq(this).attr('id');
        var cur_id = cur_node.replace("mainnode", "");

        var versatz = Math.abs($jq(this).position().left);
        $jq('#mainnode' + cur_id).data('versatz', versatz);

        if (cur_id == '6') {

            $jq.ajax({
                type: "POST",
                url: host + "ajax/promoJobsMenuConfig",
                //data: "{'node': '6'}",
                contentType: "application/json;charset=utf-8",
                dataType: "json",
                success: function (jsondata) {

                    var ul_width = $jq('#menu_subnav' + cur_id + ' ul').width();
                    ul_width = Math.abs(ul_width);
                    $jq('#mainnode' + cur_id).data('ul_width', ul_width);

                    var menu_width = $jq('#innersubnav' + cur_id).width();
                    menu_width = Math.abs(menu_width);
                    $jq('#mainnode' + cur_id).data('menu_width', menu_width);

                    var leftPromo = jsondata.leftPromo;
                    var leftPromoIs = false;
                    if (typeof leftPromo !== typeof undefined) {
                        if (leftPromo.active == '1') {
                            leftPromoIs = true;
                        }
                    }
                    if (leftPromoIs) {
                        if (leftPromo.link != '') {
                            var pre_left = '<a href="' + leftPromo.link + '" target="' + leftPromo.linktarget + '" title="' + leftPromo.title + '">';
                            var suf_left = '</a>';
                        } else {
                            var pre_left = '';
                            var suf_left = '';
                        }
                        var img_left = '<img id="pmi_left" src="' + leftPromo.imageUrl + '" alt="' + leftPromo.alt + '" title="' + leftPromo.title + '">';
                        var pmi_left = new Image();
                        pmi_left.src = leftPromo.imageUrl;
                        $jq('#menu_left_promo' + cur_id).html(pre_left + img_left + suf_left);
                        $jq('#menu_left_promo' + cur_id).addClass('promoimgwrapper');
                    }
                    var rightPromo = jsondata.rightPromo;
                    var rightPromoIs = false;
                    if (typeof rightPromo !== typeof undefined) {
                        if (rightPromo.active == '1') {
                            rightPromoIs = true;
                        }
                    }
                    if (rightPromoIs) {
                        if (rightPromo.link != '') {
                            var pre_right = '<a href="' + rightPromo.link + '" target="' + rightPromo.linktarget + '" title="' + rightPromo.title + '">';
                            var suf_right = '</a>';
                        } else {
                            var pre_right = '';
                            var suf_right = '';
                        }
                        var img_right = '<img id="pmi_right" src="' + rightPromo.imageUrl + '" alt="' + rightPromo.alt + '" title="' + rightPromo.title + '">';
                        var pmi_right = new Image();
                        pmi_right.src = rightPromo.imageUrl;
                        $jq('#menu_right_promo' + cur_id).html(pre_right + img_right + suf_right);
                        $jq('#menu_right_promo' + cur_id).addClass('promoimgwrapper');
                    }
                }
            })
        }

    });

}

